package app.kivo.store;
import android.app.*;import android.os.Bundle;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;
/** Isolated game browser: no native bridge, file access, or app credentials. */
public final class ItchGameActivity extends Activity {
 WebView game;FrameLayout stage;View custom;WebChromeClient.CustomViewCallback callback;
 public void onCreate(Bundle b){super.onCreate(b);String url=getIntent().getStringExtra("url");Uri u=Uri.parse(url==null?"":url);String h=u.getHost();if(!"https".equals(u.getScheme())||h==null||!(h.equals("itch.io")||h.endsWith(".itch.io"))){finish();return;}LinearLayout root=new LinearLayout(this);root.setOrientation(1);Button close=new Button(this);close.setText("‹ Volver a Kivo");close.setOnClickListener(v->finish());root.addView(close,new LinearLayout.LayoutParams(-1,56));stage=new FrameLayout(this);root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));game=new WebView(this);stage.addView(game,new FrameLayout.LayoutParams(-1,-1));setContentView(root);WebSettings s=game.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);game.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme());}});game.setWebChromeClient(new WebChromeClient(){public void onShowCustomView(View v,CustomViewCallback c){if(custom!=null){c.onCustomViewHidden();return;}custom=v;callback=c;stage.addView(v,new FrameLayout.LayoutParams(-1,-1));game.setVisibility(View.GONE);}public void onHideCustomView(){hideCustom();}});game.setDownloadListener((a,ua,disp,mime,len)->Toast.makeText(this,"Para instalar un APK, vuelve a la ficha del juego en Kivo.",Toast.LENGTH_LONG).show());game.loadUrl(url);}
 void hideCustom(){if(custom!=null){stage.removeView(custom);custom=null;game.setVisibility(View.VISIBLE);if(callback!=null)callback.onCustomViewHidden();callback=null;}}
 public void onBackPressed(){if(custom!=null)hideCustom();else if(game.canGoBack())game.goBack();else finish();}
 protected void onPause(){if(game!=null)game.onPause();super.onPause();}protected void onResume(){super.onResume();if(game!=null)game.onResume();}protected void onDestroy(){if(game!=null){game.stopLoading();game.destroy();}super.onDestroy();}
}
